import { Group, Mesh, PlaneGeometry, ShapeGeometry, Shape, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Text content extraction ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findItem = (role) => items.find(i => i.role === role);
  const quoteMarkItem = findItem('quote-mark');
  const quoteItem = findItem('quote');
  const attributionItem = findItem('attribution');
  const captionItem = findItem('caption');

  // --- Panel geometry helpers ---
  const panelWidth = 3.4;
  const panelHeight = 1.9;
  const cornerRadius = 0.06;
  const borderThickness = 0.006;

  function roundedRectShape(w, h, r) {
    const shape = new Shape();
    shape.moveTo(-w / 2 + r, -h / 2);
    shape.lineTo(w / 2 - r, -h / 2);
    shape.quadraticCurveTo(w / 2, -h / 2, w / 2, -h / 2 + r);
    shape.lineTo(w / 2, h / 2 - r);
    shape.quadraticCurveTo(w / 2, h / 2, w / 2 - r, h / 2);
    shape.lineTo(-w / 2 + r, h / 2);
    shape.quadraticCurveTo(-w / 2, h / 2, -w / 2, h / 2 - r);
    shape.lineTo(-w / 2, -h / 2 + r);
    shape.quadraticCurveTo(-w / 2, -h / 2, -w / 2 + r, -h / 2);
    return shape;
  }

  // Outer border
  const outerShape = roundedRectShape(
    panelWidth + 2 * borderThickness,
    panelHeight + 2 * borderThickness,
    cornerRadius + borderThickness
  );
  const borderGeo = new ShapeGeometry(outerShape);
  const borderMat = new MeshBasicNodeMaterial({ color: '#26262f', transparent: true, opacity: 0 });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.y = 0.2;
  group.add(borderMesh);

  // Inner panel with gradient
  const innerShape = roundedRectShape(
    panelWidth - 2 * borderThickness,
    panelHeight - 2 * borderThickness,
    cornerRadius - borderThickness
  );
  const innerGeo = new ShapeGeometry(innerShape);
  const uvNode = uv();
  const gradientColor = mix(color('#1a1a22'), color('#111116'), uvNode.y);
  const panelMat = new MeshStandardNodeMaterial({
    colorNode: gradientColor,
    roughness: 0.6,
    metalness: 0.2,
    clearcoat: 0.1,
    transparent: true,
    opacity: 0,
    side: ctx.THREE.DoubleSide
  });
  const panelMesh = new Mesh(innerGeo, panelMat);
  panelMesh.position.set(0, 0.2, 0.001);
  group.add(panelMesh);

  // --- Quotation mark ---
  const quoteMarkText = quoteMarkItem?.text || '"';
  const qmContainer = new Group();
  const qmMesh = ctx.fontAtlas.createText(quoteMarkText, {
    fontSize: 62,
    color: '#ff2a38',
    align: 'left',
    letterSpacing: 0,
  });
  const qmMat = new MeshStandardNodeMaterial({
    color: '#ff2a38',
    roughness: 0.5,
    metalness: 0.3,
  });
  // Replace material on the returned mesh
  if (qmMesh.isMesh) {
    qmMesh.material = qmMat;
  } else {
    qmMesh.traverse(child => {
      if (child.isMesh) child.material = qmMat;
    });
  }
  qmContainer.add(qmMesh);
  qmContainer.position.set(-1.2, 0.45, 0.04);
  qmContainer.scale.set(1.04, 1.04, 1.04);
  group.add(qmContainer);

  // --- Quote body ---
  const quoteText = quoteItem?.text || "The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.";
  const quoteMesh = ctx.fontAtlas.createText(quoteText, {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'left',
    maxWidthPx: 500,
  });
  quoteMesh.position.set(-1.2, -0.42, 0.03);
  group.add(quoteMesh);

  // --- Accent rule ---
  const ruleGeo = new PlaneGeometry(0.2, 0.02);
  const ruleMat = new MeshStandardNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.4,
    roughness: 0.6,
  });
  const ruleMesh = new Mesh(ruleGeo, ruleMat);
  ruleMesh.position.set(-1.2, -0.67, 0.03);
  group.add(ruleMesh);

  // --- Attribution ---
  const attributionText = attributionItem?.text || "M. OKAFOR";
  const attributionMesh = ctx.fontAtlas.createText(attributionText, {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
    letterSpacing: 0.08,
  });
  attributionMesh.position.set(-1.2 + 0.3, -0.67, 0.03);
  group.add(attributionMesh);

  // --- Caption ---
  const captionText = captionItem?.text || "COLLECTOR SINCE 2019";
  const captionMesh = ctx.fontAtlas.createText(captionText, {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'left',
    letterSpacing: 0.12,
  });
  captionMesh.position.set(-1.2, -0.82, 0.03);
  group.add(captionMesh);

  // --- Animation setup ---
  const tl = gsap.timeline({ paused: true });

  tl.to(borderMesh.position, { y: 0, duration: 0.5, ease: 'power2.out' }, 0)
    .to(borderMat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0)
    .to(panelMesh.position, { y: 0, duration: 0.5, ease: 'power2.out' }, 0)
    .to(panelMat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);

  tl.to(qmContainer.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
    delay: 0.35
  }, 0.5);

  // Start immediately
  tl.progress(0);
  tl.play();

  // --- Event handlers (none) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    const disposeList = [borderGeo, innerGeo, ruleGeo];
    const matList = [borderMat, panelMat, qmMat, ruleMat];

    group.traverse(child => {
      if (child.isMesh) {
        if (child.geometry && !disposeList.includes(child.geometry)) {
          child.geometry.dispose();
          disposeList.push(child.geometry);
        }
        if (child.material) {
          const mats = Array.isArray(child.material) ? child.material : [child.material];
          mats.forEach(m => {
            if (!matList.includes(m)) {
              m.dispose();
              matList.push(m);
            }
          });
        }
      }
    });

    disposeList.forEach(g => g.dispose());
    matList.forEach(m => m.dispose());
  };

  return group;
}
